// Project 38 built a solid sync emitter. Then the app around it went
// async, and three new failure modes showed up. This file plays them
// out with a fake reconnecting chat client.
import { EventEmitter } from "../38-event-emitter/refactored/emitter.js";

var bus = new EventEmitter();

// ---- Failure mode 1: waiting for an event by POLLING ----------------
// "Wait until we're connected, then send." There's no way to await an
// event, so... a spin loop with sleeps. Wasteful, laggy (up to 100ms
// late), and if the event never comes it polls FOREVER — no timeout.
var connected = false;
bus.on("connected", function () { connected = true; });

async function sendWhenConnected(msg) {
  while (!connected) {
    await new Promise(function (r) { setTimeout(r, 100); });
  }
  console.log("sent:", msg);
}

// ---- Failure mode 2: the forgotten unsubscribe = a LEAK -------------
// Every reconnect wires up handlers for the new session... without
// tearing down the old ones. Old handlers keep firing (duplicate
// message processing!) and keep every dead session object alive in
// memory via the closure. The count below just keeps climbing.
function startSession(sessionId) {
  var sessionData = { id: sessionId, buffer: [] }; // retained forever
  bus.on("message", function (m) {
    sessionData.buffer.push(m); // ALL past sessions still push!
  });
  // ...disconnect happens, reconnect calls startSession again,
  // and nobody kept the unsubscribe handle 38 so carefully returned.
}

// ---- Failure mode 3: async listeners fire-and-forget ----------------
// The emitter calls listeners synchronously. An ASYNC listener returns
// a promise nobody looks at: emit() returns before the work is done
// (ordering bugs), and a rejection becomes an unhandled-rejection
// CRASH — watch this very file die at the end, with a stack trace
// pointing nowhere near the emit() that caused it.
bus.on("save", async function (doc) {
  await new Promise(function (r) { setTimeout(r, 10); });
  if (!doc.title) throw new Error("untitled docs are unsaveable");
});

async function main() {
  startSession(1);
  startSession(2);
  startSession(3);
  console.log("message listeners after 3 reconnects:", bus.listenerCount("message")); // 3, should be 1

  bus.emit("message", "hi"); // processed by three dead sessions

  setTimeout(function () { bus.emit("connected"); }, 250);
  await sendWhenConnected("hello"); // works, via ~3 polls

  bus.emit("save", {}); // the async listener will reject...
  console.log("emit('save') returned before the save even ran");
  // ...and ~10ms later the rejection kills the process. THE END.
}

main();

# 🏋️ Practice: Async Event Emitter

Do these after reading LEARN.md and the README. Solutions are at the bottom — try each exercise before peeking.

Exercises 1, 4 and 5 need only the public API — import `AsyncEmitter` from `refactored/async-emitter.js` in a scratch file. Exercises 2 and 3 add methods to the class, so work in a *copy* of `async-emitter.js`. Everything runs offline with `node --test` or plain `node`.

## Exercises

### ⭐ 1. Pin down `once` (warm-up)

`once` exists in the class but no test targets it directly (only `waitFor` uses it). Write a test proving both halves of its contract: the listener fires exactly one time across two emits, and it detaches itself — `listenerCount` drops back to 0.

What it practices: reading a small wrapper (`once` is built on `on`) and testing its whole contract, not just the happy path.
Expected: after two `emitAsync('ping')` calls, the counter is `1` and `listenerCount('ping')` is `0`.
Hint: `once` calls `off()` *before* running your listener. Would swapping those two lines change your test's result if the listener re-emits?

### ⭐⭐ 2. `eventNames()` — what is anyone listening to?

Add an `eventNames()` method returning an array of event names that currently have **at least one** listener. Careful: when the last listener unsubscribes, its `Set` stays in the map with size 0 — an empty event must not be reported.

What it practices: interrogating the `Map`-of-`Set`s data structure, and the difference between "key exists" and "key has members".
Expected: subscribe to `'message'` and `'status'` under one `AbortController`; `eventNames()` is `['message', 'status']`; after `abort()` it is `[]`.
Hint: `[...this.#listeners]` gives `[event, set]` pairs — filter, then map.

### ⭐⭐ 3. `emitSerial` — one listener at a time

`emitAsync` starts all listeners at once (their awaits interleave). Add `emitSerial(event, ...args)`: awaits each listener **to completion before starting the next**, in registration order — for handlers that must not overlap, like writes to one file. Keep the failure policy: every listener still runs, failures are collected into one `AggregateError`.

What it practices: sequential-vs-parallel async iteration under the same error contract.
Expected: listener A awaits 30 ms then logs `'A'`; listener B logs `'B'` immediately. `emitSerial` → log is `['A', 'B']`; `emitAsync` (same setup) → `['B', 'A']`.
Hint: a `for...of` with `try { await fn(...args) } catch { failures.push(...) }` — no `Promise.allSettled` needed.

### ⭐⭐ 4. `waitForMatch` — wait for the *right* event

`waitFor` resolves on the next event, whatever its payload. Write `waitForMatch(event, predicate, { timeoutMs })`: keeps listening past payloads the predicate rejects, resolves with the first one it accepts, and cleans up its listener on success *and* on timeout. Chat scenario: wait for the message addressed to *you*, not just any message.

What it practices: composing `on` + a promise by hand — `once` can't do this, because a rejected payload must keep the subscription alive.
Expected: emit `{ to: 'bob' }` then `{ to: 'me' }` → resolves with `{ to: 'me' }`; `listenerCount` is 0 afterward; with `timeoutMs: 50` and no match it rejects after ~50 ms, count 0 again.
Hint: use `on` (not `once`); call `off()` only inside the branch where the predicate passes, and in the timeout.

### ⭐⭐⭐ 5. `waitForAny` — first of several events wins

Real connects finish with `'connected'` *or* `'error'` — awaiting only one risks waiting forever. Write `waitForAny(events, { timeoutMs })` resolving with `[eventName, payload]` for whichever fires first. The hard part is cleanup: when one event wins (or the timeout fires), the listeners on **all the other events** must detach too.

What it practices: multi-listener lifecycles — N subscriptions, one settlement, zero leaks (the whole point of this project).
Expected: `waitForAny(['connected', 'error'])`, then `emitAsync('error', 'boom')` → resolves `['error', 'boom']`; `listenerCount` is 0 for *both* events; the timeout path also leaves both at 0.
Hint: collect every unsubscribe fn in an array; write one `cleanup()` that clears the timer and calls them all; call it in every exit path.

## Solutions

### 1. `once` contract

```js
test('once fires exactly once and detaches itself', async () => {
  const bus = new AsyncEmitter();
  let calls = 0;
  bus.once('ping', () => { calls++; });
  await bus.emitAsync('ping');
  await bus.emitAsync('ping');
  assert.equal(calls, 1);
  assert.equal(bus.listenerCount('ping'), 0);
});
```

WHY: subscriptions are resources, and `once` is the smallest self-cleaning one — the test pins both that it delivered and that it *released*. The detach-before-run order inside `once` matters: if the listener itself emits the same event, the already-removed listener can't re-fire.

### 2. `eventNames()`

```js
eventNames() {
  return [...this.#listeners]
    .filter(([, set]) => set.size > 0)
    .map(([event]) => event);
}
```

```js
test('eventNames reports only events with live listeners', () => {
  const bus = new AsyncEmitter();
  const session = new AbortController();
  bus.on('message', () => {}, { signal: session.signal });
  bus.on('status', () => {}, { signal: session.signal });
  assert.deepEqual(bus.eventNames().sort(), ['message', 'status']);
  session.abort();
  assert.deepEqual(bus.eventNames(), []);
});
```

WHY: `off` deletes the listener from its `Set` but leaves the empty `Set` in the map, so "has the key" and "has listeners" genuinely differ — the filter on `set.size > 0` is the exercise. A debugging method like this is also the natural companion to the leak smoke-alarm: it shows *what* is leaking.

### 3. `emitSerial`

```js
async emitSerial(event, ...args) {
  const listeners = [...(this.#listeners.get(event) ?? [])];
  const failures = [];
  for (const fn of listeners) {
    try { await fn(...args); } catch (err) { failures.push(err); }
  }
  if (failures.length > 0) {
    throw new AggregateError(failures, `${failures.length} listener(s) failed for "${event}"`);
  }
  return listeners.length;
}
```

```js
test('emitSerial runs listeners one at a time, in order', async () => {
  const bus = new AsyncEmitter();
  const log = [];
  bus.on('save', async () => {
    await new Promise((r) => setTimeout(r, 30));
    log.push('A');
  });
  bus.on('save', () => { log.push('B'); });
  await bus.emitSerial('save');
  assert.deepEqual(log, ['A', 'B']); // emitAsync would give ['B', 'A']
});
```

WHY: `emitAsync` maps all listeners into promises up front, so they interleave; the sequential `for...of` awaits each before starting the next — the classic parallel-vs-serial fork in async code. The error policy is unchanged on purpose: every listener still gets its delivery and failures surface together, so callers switching between the two methods only change *timing*, never error behavior.

### 4. `waitForMatch`

```js
waitForMatch(event, predicate, { timeoutMs } = {}) {
  return new Promise((resolve, reject) => {
    let timer;
    const off = this.on(event, (...args) => {
      const value = args.length <= 1 ? args[0] : args;
      if (!predicate(value)) return; // not ours — stay subscribed
      clearTimeout(timer);
      off();
      resolve(value);
    });
    if (timeoutMs !== undefined) {
      timer = setTimeout(() => {
        off();
        reject(new Error(`Timed out after ${timeoutMs}ms waiting for matching "${event}"`));
      }, timeoutMs);
    }
  });
}
```

```js
test('waitForMatch skips non-matching payloads and cleans up', async () => {
  const bus = new AsyncEmitter();
  const wait = bus.waitForMatch('message', (m) => m.to === 'me');
  await bus.emitAsync('message', { to: 'bob' });
  await bus.emitAsync('message', { to: 'me' });
  assert.deepEqual(await wait, { to: 'me' });
  assert.equal(bus.listenerCount('message'), 0);
});
```

WHY: `once` detaches after the first delivery, but here the first delivery may be the wrong one — so the subscription must survive rejections and end itself only on match or timeout. Every exit path (match, timeout) both clears the timer and unsubscribes: that pairing is the resource-lifecycle discipline the README calls "every `on` needs an owner who guarantees the matching `off`".

### 5. `waitForAny`

```js
waitForAny(events, { timeoutMs } = {}) {
  return new Promise((resolve, reject) => {
    let timer;
    const offs = [];
    const cleanup = () => {
      clearTimeout(timer);
      for (const off of offs) off();
    };
    for (const event of events) {
      offs.push(this.on(event, (...args) => {
        cleanup();
        resolve([event, args.length <= 1 ? args[0] : args]);
      }));
    }
    if (timeoutMs !== undefined) {
      timer = setTimeout(() => {
        cleanup();
        reject(new Error(`Timed out after ${timeoutMs}ms waiting for any of: ${events.join(', ')}`));
      }, timeoutMs);
    }
  });
}
```

```js
test('waitForAny settles on the first event and detaches ALL listeners', async () => {
  const bus = new AsyncEmitter();
  const wait = bus.waitForAny(['connected', 'error']);
  await bus.emitAsync('error', 'boom');
  assert.deepEqual(await wait, ['error', 'boom']);
  assert.equal(bus.listenerCount('connected'), 0); // the loser detached too
  assert.equal(bus.listenerCount('error'), 0);
});
```

WHY: one settlement owns N subscriptions, so the win/timeout handler must tear down all of them — forgetting the *losing* listeners is exactly the reconnect leak from the original, in miniature. Funnelling every exit through one `cleanup()` is the same move as tying a session's subscriptions to one `AbortController`: many resources, one owner, one release point. (The promise can't double-settle: `resolve` after `reject` — or a second `resolve` — is ignored by promise semantics, but cleanup still must run exactly once for the counts to hit zero.)

/**
 * AsyncEmitter — project 38's emitter, grown up for async apps:
 *
 *   on(event, fn, {signal})   — AbortSignal tears down WHOLE GROUPS of
 *                               subscriptions at once (the leak fix)
 *   waitFor(event, {timeoutMs}) — the next event as a PROMISE
 *                               (replaces polling loops)
 *   emitAsync(event, ...args) — runs listeners (sync or async) to
 *                               completion; failures collected, never
 *                               lost to the unhandled-rejection void
 *
 * Plus the leak smoke-alarm: exceeding maxListeners warns once —
 * loudly, with the event name — because a climbing listener count is
 * almost always a forgotten unsubscribe in a re-run setup path.
 */
export class AsyncEmitter {
  #listeners = new Map(); // event -> Set of fns
  #warned = new Set();
  #maxListeners;
  #warn;

  constructor({ maxListeners = 10, warn = console.warn } = {}) {
    this.#maxListeners = maxListeners;
    this.#warn = warn; // injectable, so tests can assert the warning
  }

  /**
   * Subscribe. Still returns an unsubscribe fn (38's contract), but
   * also accepts an AbortSignal — the DOM's own cleanup pattern.
   * One controller can own every subscription of a session:
   * abort() on disconnect and they ALL detach. You can't forget a
   * handle you never had to keep.
   */
  on(event, listener, { signal } = {}) {
    if (signal?.aborted) return () => {};

    if (!this.#listeners.has(event)) this.#listeners.set(event, new Set());
    const set = this.#listeners.get(event);
    set.add(listener);

    if (set.size > this.#maxListeners && !this.#warned.has(event)) {
      this.#warned.add(event);
      this.#warn(
        `Possible listener leak: ${set.size} listeners on "${event}" ` +
        `(max ${this.#maxListeners}). Forgotten unsubscribe in a reconnect path?`,
      );
    }

    const off = () => {
      set.delete(listener);
      signal?.removeEventListener('abort', off); // don't leak into the signal either
    };
    signal?.addEventListener('abort', off, { once: true });
    return off;
  }

  once(event, listener, opts) {
    const off = this.on(event, (...args) => {
      off();
      listener(...args);
    }, opts);
    return off;
  }

  /**
   * The next occurrence of `event`, as a promise. This is what kills
   * the polling loop: `await bus.waitFor('connected')` — no spin, no
   * lag, and with `timeoutMs` set it can't wait forever (project 43's
   * deadline lesson: hangs are worse than errors).
   */
  waitFor(event, { timeoutMs, signal } = {}) {
    return new Promise((resolve, reject) => {
      let timer;
      const off = this.once(event, (...args) => {
        clearTimeout(timer);
        resolve(args.length <= 1 ? args[0] : args);
      }, { signal });

      if (timeoutMs !== undefined) {
        timer = setTimeout(() => {
          off();
          reject(new Error(`Timed out after ${timeoutMs}ms waiting for "${event}"`));
        }, timeoutMs);
      }
      signal?.addEventListener('abort', () => {
        clearTimeout(timer);
        reject(new Error(`Aborted while waiting for "${event}"`));
      }, { once: true });
    });
  }

  /**
   * Deliver to every listener and AWAIT the async ones. allSettled
   * semantics (project 52's lesson): every listener gets its
   * delivery, then all failures surface together in one
   * AggregateError — none evaporate as unhandled rejections.
   */
  async emitAsync(event, ...args) {
    const listeners = [...(this.#listeners.get(event) ?? [])];
    const results = await Promise.allSettled(
      listeners.map(async (fn) => fn(...args)), // async wrapper: sync throws become rejections
    );
    const failures = results.filter((r) => r.status === 'rejected').map((r) => r.reason);
    if (failures.length > 0) {
      throw new AggregateError(failures, `${failures.length} listener(s) failed for "${event}"`);
    }
    return listeners.length;
  }

  listenerCount(event) {
    return this.#listeners.get(event)?.size ?? 0;
  }
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { AsyncEmitter } from './async-emitter.js';

test('basic on/emitAsync/off still works (38 compatibility)', async () => {
  const bus = new AsyncEmitter();
  const seen = [];
  const off = bus.on('msg', (m) => seen.push(m));
  await bus.emitAsync('msg', 'a');
  off();
  await bus.emitAsync('msg', 'b');
  assert.deepEqual(seen, ['a']);
});

test('AbortSignal detaches a whole GROUP of subscriptions at once', async () => {
  const bus = new AsyncEmitter();
  const session = new AbortController();
  const seen = [];
  bus.on('message', (m) => seen.push(`msg:${m}`), { signal: session.signal });
  bus.on('typing', (u) => seen.push(`typing:${u}`), { signal: session.signal });

  await bus.emitAsync('message', 1);
  session.abort(); // disconnect: one call tears down the whole session
  await bus.emitAsync('message', 2);
  await bus.emitAsync('typing', 'ada');

  assert.deepEqual(seen, ['msg:1']);
  assert.equal(bus.listenerCount('message'), 0);
  assert.equal(bus.listenerCount('typing'), 0);
});

test('an already-aborted signal never subscribes at all', async () => {
  const bus = new AsyncEmitter();
  const ac = new AbortController();
  ac.abort();
  bus.on('x', () => { throw new Error('should never run'); }, { signal: ac.signal });
  await bus.emitAsync('x');
  assert.equal(bus.listenerCount('x'), 0);
});

test('the reconnect-leak scenario from the original, fixed', () => {
  const warnings = [];
  const bus = new AsyncEmitter({ maxListeners: 10, warn: (w) => warnings.push(w) });

  let current = null;
  function startSession(id) {
    current?.abort(); // tear down the previous session's subscriptions
    current = new AbortController();
    bus.on('message', () => {}, { signal: current.signal });
  }
  for (let i = 1; i <= 50; i++) startSession(i);

  assert.equal(bus.listenerCount('message'), 1); // the original climbed to 50
  assert.deepEqual(warnings, []);
});

test('leak smoke-alarm: exceeding maxListeners warns ONCE, naming the event', () => {
  const warnings = [];
  const bus = new AsyncEmitter({ maxListeners: 3, warn: (w) => warnings.push(w) });
  for (let i = 0; i < 6; i++) bus.on('data', () => {});
  assert.equal(warnings.length, 1); // once, not a warning-spam firehose
  assert.match(warnings[0], /"data"/);
  assert.match(warnings[0], /leak/i);
});

test('waitFor: awaiting an event beats polling for it', async () => {
  const bus = new AsyncEmitter();
  setTimeout(() => bus.emitAsync('connected', { user: 'ada' }), 10);
  const payload = await bus.waitFor('connected');
  assert.deepEqual(payload, { user: 'ada' });
  assert.equal(bus.listenerCount('connected'), 0); // waitFor cleans up after itself
});

test('waitFor with timeoutMs: the event never coming is an ERROR, not a hang', async () => {
  const bus = new AsyncEmitter();
  await assert.rejects(
    () => bus.waitFor('connected', { timeoutMs: 20 }),
    /Timed out after 20ms waiting for "connected"/,
  );
  assert.equal(bus.listenerCount('connected'), 0); // timeout also unsubscribes
});

test('emitAsync AWAITS async listeners — emit-then-done ordering is real', async () => {
  const bus = new AsyncEmitter();
  const order = [];
  bus.on('save', async () => {
    await new Promise((r) => setTimeout(r, 10));
    order.push('saved');
  });
  await bus.emitAsync('save');
  order.push('after emit');
  assert.deepEqual(order, ['saved', 'after emit']); // the original logged the reverse
});

test('async listener failures are COLLECTED, not unhandled rejections', async () => {
  const bus = new AsyncEmitter();
  const seen = [];
  bus.on('save', async () => { throw new Error('untitled docs are unsaveable'); });
  bus.on('save', async (doc) => { seen.push(doc); }); // still runs (isolation)
  bus.on('save', () => { throw new Error('sync throw'); }); // sync failure, same treatment

  await assert.rejects(
    () => bus.emitAsync('save', { id: 7 }),
    (err) => err instanceof AggregateError && err.errors.length === 2,
  );
  assert.deepEqual(seen, [{ id: 7 }]); // one bad listener never blocks the others
});
